async function resolveResourcesStorageDir() {
  const fs7 = getFileSystem();
  return fs7.path.join(fs7.env.homedir(), ".uip", "case-resources");
}
async function saveResourceIndex(resources, resourceType) {
  const fs7 = getFileSystem();
  const dir2 = await resolveResourcesStorageDir();
  await fs7.mkdir(dir2);
  const indexPath = fs7.path.join(dir2, `${resourceType}-index.json`);
  const content = JSON.stringify(resources, null, 2);
  await fs7.writeFile(indexPath, content);
  logger.debug(`Saved ${resources.length} ${resourceType} resources to index. Updating metadata...`);
  const hash2 = await hashContent(content);
  await saveIndexMetadata2({
    lastSync: Date.now(),
    count: resources.length,
    hash: hash2
  }, resourceType);
  return resources.length;
}
async function loadResourceIndex(resourceType) {
  const fs7 = getFileSystem();
  const dir2 = await resolveResourcesStorageDir();
  const indexPath = fs7.path.join(dir2, `${resourceType}-index.json`);
  if (!await fs7.exists(indexPath)) {
    throw new Error("No resource index found. Please run 'uip maestro case registry pull' to sync resources first.");
  }
  const [readError, content] = await catchError(fs7.readFile(indexPath, "utf-8"));
  if (readError) {
    throw new Error(`Failed to load resource index: ${readError instanceof Error ? readError.message : String(readError)}`);
  }
  if (content === null || content.trim() === "") {
    throw new Error("No resource index found. Please run 'uip maestro case registry pull' to sync resources first.");
  }
  const [parseError, parsed] = await catchError(Promise.resolve().then(() => JSON.parse(content)));
  if (parseError) {
    throw new Error("No resource index found. Please run 'uip maestro case registry pull' to sync resources first.");
  }
  return parsed;
}
async function saveIndexMetadata2(metadata, resourceType) {
  const fs7 = getFileSystem();
  const dir2 = await resolveResourcesStorageDir();
  await fs7.mkdir(dir2);
  const metaPath = fs7.path.join(dir2, `${resourceType}-index.meta.json`);
  await fs7.writeFile(metaPath, JSON.stringify(metadata, null, 2));
}
async function loadIndexMetadata2(resourceType) {
  const fs7 = getFileSystem();
  const dir2 = await resolveResourcesStorageDir();
  const metaPath = fs7.path.join(dir2, `${resourceType}-index.meta.json`);
  if (!await fs7.exists(metaPath)) {
    return null;
  }
  const [error90, metadata] = await catchError((async () => {
    const content = await fs7.readFile(metaPath, "utf-8");
    if (content === null) {
      return null;
    }
    return JSON.parse(content);
  })());
  if (error90) {
    return null;
  }
  return metadata;
}

// src/services/connector-lookup-service.ts
async function lookupTypeCacheEntry(uiPathActivityTypeId, type) {
  const entries = await loadResourceIndex(type);
  const entry = entries.find((e) => e.uiPathActivityTypeId === uiPathActivityTypeId);
  if (!entry) {
    throw new Error(`No entry found in ${type} with uiPathActivityTypeId: ${uiPathActivityTypeId}`);
  }
  const [parseError, config3] = catchError(() => JSON.parse(entry.configuration));
  if (parseError) {
    throw new Error(`Failed to parse configuration for "${entry.displayName}" in ${type}: ${parseError.message}`);
  }
  if (!config3.connectorKey) {
    throw new Error(`Configuration for "${entry.displayName}" in ${type} is missing connectorKey`);
  }
  return { entry, config: config3 };
}
async function lookupConnectorDisplayName(packageId) {
  if (typeof packageId !== "number")
    return null;
  const [err2, packages] = await catchError(loadResourceIndex("typecache-packages"));
  if (err2)
    return null;
  const pkg = packages.find((p) => p.id === packageId);
  return pkg?.displayName ?? null;
}
async function fetchConnectorConnections(connectorKey) {
  const [apiError, api3] = await catchError(createApiClient(ConnectorsApi));
  if (apiError) {
    throw new Error(`Failed to create Integration Service client: ${apiError.message}`);
  }
  const [fetchError, connections] = await catchError(api3.apiV1ConnectorsKeyOrIdConnectionsGet({
    keyOrId: connectorKey,
    allFolders: true,
    folderDefaults: true
  }));
  if (fetchError) {
    throw new Error(`Failed to fetch connections for connector "${connectorKey}": ${fetchError.message}`);
  }
  return connections;
}

