// src/services/resourcesSyncService.ts
var CACHE_EXPIRATION2 = 24 * 60 * 60 * 1000;
async function pullResources(options = {}, resourceType) {
  const { force = false, solutionId = undefined } = options;
  if (force) {
    const refreshResult2 = await refreshResources(resourceType, solutionId);
    const meta4 = await loadIndexMetadata2(resourceType);
    return {
      syncedCount: refreshResult2.count || meta4?.count || 0,
      fromCache: false,
      cacheWritten: refreshResult2.cacheWritten,
      info: refreshResult2.info
    };
  }
  const meta3 = await loadIndexMetadata2(resourceType);
  if (meta3) {
    const ageMs = Date.now() - meta3.lastSync;
    if (ageMs < CACHE_EXPIRATION2) {
      return {
        syncedCount: meta3.count,
        fromCache: true,
        ageMinutes: Math.round(ageMs / 60000)
      };
    }
  }
  const refreshResult = await refreshResources(resourceType, solutionId);
  const refreshedMeta = await loadIndexMetadata2(resourceType);
  return {
    syncedCount: refreshResult.count || refreshedMeta?.count || 0,
    fromCache: false,
    cacheWritten: refreshResult.cacheWritten,
    info: refreshResult.info
  };
}
async function refreshResources(resourceType, solutionId) {
  const oldMeta = await loadIndexMetadata2(resourceType);
  const pullResult = await pullRemoteResources(resourceType, solutionId);
  const resources = pullResult.resources;
  if (!pullResult.cacheable) {
    return {
      cacheWritten: false,
      count: resources.length,
      info: pullResult.info
    };
  }
  const content = JSON.stringify(resources, null, 2);
  const newHash = await hashContent(content);
  if (oldMeta && oldMeta.hash === newHash) {
    await saveIndexMetadata2({
      lastSync: Date.now(),
      count: oldMeta.count,
      hash: oldMeta.hash
    }, resourceType);
    return {
      cacheWritten: true,
      count: oldMeta.count
    };
  }
  await saveResourceIndex(resources, resourceType);
  return {
    cacheWritten: true,
    count: resources.length
  };
}
async function pullRemoteResources(resourceType, solutionId) {
  switch (resourceType) {
    case "action-apps":
      return {
        resources: await listActionApps(),
        cacheable: true
      };
    case "agent":
    case "process":
    case "api":
    case "processOrchestration":
    case "caseManagement":
      return {
        resources: await listProcessEntities({
          entitySubType: resourceType
        }),
        cacheable: true
      };
    case "typecache-activities":
      return {
        resources: await searchActivities(),
        cacheable: true
      };
    case "typecache-triggers":
      return {
        resources: await searchTriggers(),
        cacheable: true
      };
    case "typecache-packages":
      return {
        resources: await searchPackages(),
        cacheable: true
      };
    case "solution":
      if (!solutionId) {
        return {
          resources: [],
          cacheable: false,
          info: "Solution ID not provided. Skipping solution entities pull."
        };
      }
      return {
        resources: await listSolutionEntities(solutionId),
        cacheable: true
      };
    default: {
      return {
        resources: [],
        cacheable: false,
        info: `Unknown resource type: ${resourceType}`
      };
    }
  }
}
async function getResourcesWithCacheFallback(resourceType) {
  const [error90, resources] = await catchError(loadResourceIndex(resourceType));
  if (error90) {
    const errorMessage2 = error90 instanceof Error ? error90.message : String(error90);
    if (!errorMessage2.includes("No resource index found")) {
      throw error90;
    }
    const pullResult = await pullRemoteResources(resourceType);
    if (pullResult.cacheable) {
      await saveResourceIndex(pullResult.resources, resourceType);
    }
    return pullResult.resources;
  }
  return resources;
}
async function listResources(resourceType) {
  return getResourcesWithCacheFallback(resourceType);
}
async function searchResources(keyword, resourceType) {
  return searchResourcesWithFilters(keyword, undefined, resourceType);
}
async function searchResourcesWithFilters(keyword, filters, resourceType) {
  const types2 = resourceType ? [resourceType] : [...RESOURCE_TYPES];
  const settled = await Promise.allSettled(types2.map((type) => getResourcesWithCacheFallback(type).then((resources) => ({
    type,
    resources
  }))));
  const results = [];
  const failedTypes = [];
  for (let i2 = 0;i2 < settled.length; i2++) {
    const result = settled[i2];
    if (result.status !== "fulfilled") {
      const reason = result.reason;
      failedTypes.push({
        type: types2[i2],
        error: reason instanceof Error ? reason.message : String(reason)
      });
      continue;
    }
    const { type, resources } = result.value;
    const matched = searchWithFilters2(resources, keyword, filters);
    for (const resource of matched) {
      results.push({ resourceType: type, resource });
    }
  }
  if (failedTypes.length === types2.length) {
    throw new Error(`Failed to load resources for all types: ${failedTypes.map((f) => f.type).join(", ")}`);
  }
  return { results, failedTypes };
}
async function getResources(identifier, resourceType) {
  const typesToSearch = resourceType ? GET_SEARCHABLE_TYPES.filter((t10) => t10.type === resourceType) : GET_SEARCHABLE_TYPES;
  const settled = await Promise.allSettled(typesToSearch.map(({ type, idField }) => getResourcesWithCacheFallback(type).then((resources) => ({
    type,
    idField,
    resources
  }))));
  const matches = [];
  for (const result of settled) {
    if (result.status !== "fulfilled")
      continue;
    const { type, idField, resources } = result.value;
    for (const resource of resources) {
      if (resource[idField] === identifier) {
        matches.push({ resourceType: type, resource });
      }
    }
  }
  return matches;
}

// src/utils/filter-parser.ts
var VALID_FIELDS = [
  "name",
  "description",
  "category",
  "connectorKey",
  "tags"
];
var VALID_OPERATORS = [
  "equals",
  "contains",
  "in",
  "startsWith",
  "endsWith"
];

class FilterParseError2 extends Error {
  code;
  token;
  constructor(message, code, token) {
    super(message);
    this.name = "FilterParseError";
    this.code = code;
    this.token = token;
  }
}
function parseFilterString2(filterStr) {
  const parts = filterStr.split(",").map((p) => p.trim()).filter(Boolean);
  const filters = [];
  for (const part of parts) {
    const eqIndex = part.indexOf("=");
    if (eqIndex === -1) {
      throw new FilterParseError2(`Invalid filter token: '${part}'. Expected format: 'field=value' or 'field:operator=value'`, "INVALID_FORMAT", part);
    }
    const lhs = part.slice(0, eqIndex);
    const value = part.slice(eqIndex + 1);
    const colonIndex = lhs.indexOf(":");
    let field;
    let operator;
    if (colonIndex === -1) {
      field = lhs;
      operator = "equals";
    } else {
      field = lhs.slice(0, colonIndex);
      operator = lhs.slice(colonIndex + 1);
    }
    if (!VALID_FIELDS.includes(field)) {
      throw new FilterParseError2(`Invalid filter field: '${field}'. Supported fields: ${VALID_FIELDS.join(", ")}`, "INVALID_FIELD", field);
    }
    if (!VALID_OPERATORS.includes(operator)) {
      throw new FilterParseError2(`Invalid filter operator: '${operator}'. Supported operators: ${VALID_OPERATORS.join(", ")}`, "INVALID_OPERATOR", operator);
    }
    filters.push({
      field,
      operator,
      value
    });
  }
  return { filters, logic: "AND" };
}

