function requireTaskEntryCondition(task, conditionId, taskId) {
  const condition = (task.entryConditions ?? []).find((c) => c.id === conditionId);
  if (!condition) {
    throw new Error(`Entry condition not found with id: ${conditionId} in task: ${taskId}`);
  }
  return condition;
}
