// src/services/action-schema-api.ts
async function getActionSchema(params) {
  const loginStatus2 = await getLoginStatusAsync();
  if (loginStatus2.loginStatus !== "Logged in" || !loginStatus2.baseUrl || !loginStatus2.organizationId || !loginStatus2.tenantId || !loginStatus2.accessToken) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const query = new URLSearchParams({
    appSystemName: params.systemName,
    version: String(params.deployVersion)
  });
  const url3 = `${loginStatus2.baseUrl}/${loginStatus2.organizationId}/apps_/default/api/v1/default/action-schema?${query}`;
  const response = await fetch(url3, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${loginStatus2.accessToken}`,
      "Content-Type": "application/json",
      "X-Uipath-Tenantid": loginStatus2.tenantId,
      Accept: "application/json"
    }
  });
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Action schema request failed: ${response.status} ${response.statusText} - ${errorText}`);
  }
  return await response.json();
}

// src/services/entry-point-api.ts
async function getEntryPointDetails(params) {
  const loginStatus2 = await getLoginStatusAsync();
  if (loginStatus2.loginStatus !== "Logged in" || !loginStatus2.baseUrl || !loginStatus2.organizationId || !loginStatus2.tenantName || !loginStatus2.tenantId || !loginStatus2.accessToken) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const key = `${encodeURIComponent(params.processKey)}:${encodeURIComponent(params.processVersion)}`;
  const path3 = `/odata/Processes/UiPath.Server.Configuration.OData.GetPackageEntryPointsV2(key='${key}')`;
  const query = new URLSearchParams({ feedId: params.feedId });
  const url3 = `${loginStatus2.baseUrl}/${loginStatus2.organizationId}/${loginStatus2.tenantName}/orchestrator_${path3}?${query}`;
  const headers = {
    Authorization: `Bearer ${loginStatus2.accessToken}`,
    "Content-Type": "application/json",
    "X-Uipath-Tenantid": loginStatus2.tenantId,
    Accept: "application/json"
  };
  if (params.folderKey) {
    headers["x-uipath-folderkey"] = params.folderKey;
  }
  const response = await fetch(url3, {
    method: "GET",
    headers
  });
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Entry point details request failed: ${response.status} ${response.statusText} - ${errorText}`);
  }
  const data = await response.json();
  return data.value;
}

